import{_ as t,a0 as n,w as o,s as l,I as i,x as f,a1 as O,A as r,ao as b}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const A=JSON.parse('{"title":"Apache OpenOffice 與 LibreOffice 之間的抉擇 | LCTT x X-CMD","titleTemplate":false,"description":"Apache OpenOffice 與 LibreOffice 之間的抉擇 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Apache OpenOffice 與 LibreOffice 之間的抉擇 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Apache OpenOffice 與 LibreOffice 之間的抉擇 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/Apache OpenOffice vs. LibreOffice","title":"Apache OpenOffice 與 LibreOffice 之間的抉擇","tag":"201311","desc":""},"relativePath":"201311/Apache OpenOffice vs. LibreOffice.md","filePath":"[post].md"}'),c={name:"201311/Apache OpenOffice vs. LibreOffice.md"};function L(s,e,a,d,u,m){const p=n("Link");return o(),l("div",null,[e[18]||(e[18]=i("h1",{id:"apache-openoffice-與-libreoffice-之間的抉擇",tabindex:"-1"},[f("Apache OpenOffice 與 LibreOffice 之間的抉擇 "),i("a",{class:"header-anchor",href:"#apache-openoffice-與-libreoffice-之間的抉擇","aria-label":"Permalink to “Apache OpenOffice 與 LibreOffice 之間的抉擇”"},"​")],-1)),e[19]||(e[19]=i("blockquote",null,[i("p",null,"這兩個開源辦公套件產品很相似，然而某一個貌似已經開始具有輕微的領先優勢……")],-1)),i("p",null,[O(p,{href:"http://www.openoffice.org/"},{default:r(()=>[...e[0]||(e[0]=[f("Apache OpenOffice",-1)])]),_:1}),e[2]||(e[2]=f("和",-1)),O(p,{href:"http://www.libreoffice.org/"},{default:r(()=>[...e[1]||(e[1]=[f("LibreOffice",-1)])]),_:1}),e[3]||(e[3]=f("都是OpenOffice.org的現代衍生產品。最近幾年，幾乎所有的Linux發行版都將LibreOffice作為它們的默認辦公套件。然而，過去18個月來，OpenOffice作為Apache項目又重新回到了人們的視線，對於這兩款全功能辦公套件，現在，自由軟件用户可以進行二選一咯~",-1))]),e[20]||(e[20]=b("<p>然而即使是用户，在兩種幾乎一樣的選擇中做決定也會有困難。三年前，這哥兒倆分了家，三年時間，這對於軟件開發來説是很長的一段時間，即使是這樣，OpenOffice和LibreOffice之間的不同卻剛剛開始顯現。除去那些明顯已經去掉的過時特性，單説功能集合與基本邏輯，自從OpenOffice.org時代以來，這兩者都幾乎沒有什麼大的改變。</p><p>縱觀整個套件，只有個別應用裏能發現一些新功能，主要集中在Writer的文字處理方面。其實，它們兩者之間的大部分區別主要存在於更高的層面，例如對格式和字體的支持、對插件擴展的政策等，更多的不同，則體現在是否緊跟時代，以及對標準化接口的努力程度上。</p><p>###具體各程序間的區別###</p><p>LibreOffice和OpenOffice之間的程序大部分都是一樣的。例如它倆的Draw，看起來完全沒有區別；再如Impress，主要的區別就是LibreOffice的最新版支持使用Android設備控制幻燈片放映；除了幻燈片背景以外，兩者其他方面沒什麼不同，都能很好的勝任日常使用，除非有特殊偏好，用户選擇哪一款都可以；同樣，在Calc電子製表軟件中，兩者最大的區別就是你可以在LibreOffice裏創建數據表單。</p><p>即使在用户最常用的Writer程序中，兩者的區別也很小。LibreOffice這邊，編輯窗口的底部狀態欄現在新包含了一個字詞計數器，審閲標籤也不再侷限於某個單個點，現在可以附加在配圖上，另外，LibreOffice終於解決了“腳註無法緊靠對應文本顯示”的bug，除此以外，LibreOffice還添加了一個簡易搜索欄，與web瀏覽器上的那種類似，同時，去掉了圖形水平線的選項，這個功能過去十幾年來幾乎從沒人用過。</p><p>###格式與字體###</p><p>一些更明顯的區別體現在格式分類與字體支持上。例如，OpenOffice始終支持一些較老的保存格式，像AportisDoc（Palm版）和Pocket Word。另外，它也可以打開.docx格式的文件，但是無法像LibreOffice一樣將文檔保存為docx格式。</p><p>LibreOffice同樣在字體支持方面佔有優勢。它對多語言和高級排版工藝始終有較好的支持，因此最新發布版本能夠支持OpenType這樣的現代字體首選格式。更重要的，通過“文件-&gt;屬性-&gt;字體”，你能夠將字體嵌入到文檔中去，無需任何繁瑣操作，就能確保字體的兼容性。</p><p>這樣的特性使得LibreOffice在面對微軟Office用户轉換格式的時候，得到了決定性的1分。因為通常OpenOffice和LibreOffice都無法很好處理微軟格式的文檔，特別是那些又有文字表格又有圖形對象再加上覆雜格式的文檔。因此，如果你要共享複雜一些的文檔，例如宣傳手冊，最好使用PDF格式，而不是Open文檔格式（ODF）。</p><p>然而，如果你確實需要轉換一些本地或微軟的文檔，LibreOffice擁有一些決定性優勢。它不僅能讀寫大多數微軟文檔，而且它對字體替換處理的很好，而這正是文檔格式轉換時要面臨的一個主要問題。儘管其他問題仍有不少，例如在特性實現上有所不同，但LibreOffice在處理微軟Office文檔時確實應該是一個更可靠的選擇。</p><p>###對待插件擴展的政策###</p><p>OpenOffice和LibreOffice兩者都能很好的支持插件擴展，想要加強或替換某個特性的時候，用户只需要幾分鐘就能下載並安裝完畢。大多數情況下，同一個擴展，在OpenOffice和LibreOffice上面都能工作的很好。</p><p>區別就在於，使用LibreOffice時，你無需親自安裝那些最流行的插件擴展。相反，LibreOffice已經幫你安裝整合好了。例如，基本語法校驗工具Lightproof、資料庫彙總和打印工具ReportBuilder、演示文稿壓縮工具PresentationMinimizer、Blog用户喜歡的WikiPublisher、還有幻燈片配置工具PresentationConsole等等。</p><p>以上這些擴展在OpenOffice下同樣可用。與前者不同的是，使用OpenOffice時，你首先需要知道有這些擴展，然後專門去找到它們，這樣一來，很大程度上限制了新用户對很多功能的體驗。因此，當OpenOffice在最近發佈的版本中嘗試努力提供更好用的現代模板和剪貼畫時，這樣的疏漏就成了一個非常嚴重的不足，特別是當它很容易彌補的時候，（更何況LibreOffice同時也提供了自家最新的模板和剪貼畫）。</p><p>###界面的更新換代###</p><p>在OpenOffice.org屬於Sun和Oracle的12年日子裏，它的界面和許多的其它功能一樣，幾乎被丟在遺忘的角落。如今的結果就是，OpenOffice和LibreOffice作為套件產品，都各自擁有一整套優秀的功能，但是它們的界面卻仍停留在上世紀90年代的水平。只有表面上的一些老舊界面被移除，其實大部分仍然亟待更新。</p><p>在最新的發佈中，OpenOffice試圖徹底更新自己的界面的努力主要集中在“邊欄”上。這一特性，你可以通過“工具-&gt;選項-&gt;LibreOffice-&gt;高級”打開，它被標記為“試驗性”的。</p><p>邊欄是一組功能集合，主要用於用户手動格式化。這一特性便於用户應用樣式，因為如果用户關注在文章邏輯上，很容易忽略編排的樣式。然而，最好的是，它大大簡化了格式化字符和段落的選項卡，例如所有應用程序中都有的邊框選項卡，以及電子表格單元格中的“格式”選項卡。幸運的是，邊欄還重新定義了菜單和樣式對話框窗口的概念。</p><p>LibreOffice還擁有更多的“冒險創新精神”，例如，與邊欄類似，Impress中的任務面板，摘要顯示了大多數幻燈片設計步驟中要用到的選項卡名稱。</p><p>在Writer編輯窗口中，LibreOffice的大部分界面已經完成改進，窗口底部的狀態欄中，添加了一個字詞計數器，原本負責管理和編輯模板的狹窄子菜單，如今也已被高端大氣上檔次的流線形按鈕所取代。</p><p>更明顯的，LibreOffice中的主文本框架被精減為四個邊角的十字準線。同樣的，頁眉和頁腳也默認改為不可見，要想找到它們，四個小直角標明瞭它們的邊界位置，點擊就可以出現。</p><p>不太成功的一點改進是LibreOffice中管理頁眉頁腳的編輯窗口中的選項卡。雖然這個選項卡事實上是為了便於手動調整格式，但是讓人鬱悶的是，當在新一頁的第一行輸入的時候，已經輸入的一部分總是會自動隱藏起來。</p><p>儘管LibreOffice還重組了許多對話窗口的選項，但是這些努力遠沒有結束。有時，開發人員會讓LibreOffice變成傳統框架與現代極簡藝術的混合體，看起來有些不倫不類，但是，至少LibreOffice正在嘗試着解決長期擱置的界面問題，而這些，OpenOffice甚至都還沒來得及意識到。</p><p>###做出選擇###</p><p>如果文檔不超過2到3頁，一般用户可能會時常看看標題欄看自己用的是LibreOffice還是OpenOffice。然而，對於進階用户而言，LibreOffice目前可能更有優勢。優勢並不算大，但是很明顯。</p><p>這一優勢的確很難被忽略。原因首先是，在LibreOffice已經確立了好幾個月時間優勢的情況下，OpenOffice卻仍在專注於管理權和代碼審計，這些工作也許有幫助，也有必要，但是普通用户更願意看到他們對代碼做出更多的改進工作。</p>",26)),i("p",null,[e[5]||(e[5]=f("其次，LibreOffice的開發人員大部分是",-1)),O(p,{href:"https://en.wikipedia.org/wiki/Go-oo"},{default:r(()=>[...e[4]||(e[4]=[f("Go-oo",-1)])]),_:1}),e[6]||(e[6]=f("的前成員，這是OpenOffice.org的一個非官方分支，以“快速完善”為目標。當Apache OpenOffice項目組還在籌建中的時候，LibreOffice就已經吸引了全世界酷愛編程、熱衷變革的天才們。",-1))]),e[21]||(e[21]=i("p",null,"沒有人做過準確的調查，但是我印象中，當OpenOffice.org社區分家的時候，大部分富於冒險創新精神的貢獻者都選擇了LibreOffice，同時，有一些半獨立的文檔小組，在謹慎地同時為兩個項目工作。",-1)),e[22]||(e[22]=i("p",null,"其實，LibreOffice最重要的優勢或許可以稱之為“吸血許可證”。怎麼個意思呢？就是OpenOffice的Apache許可證兼容LibreOffice的Lesser GNU通用公共許可證，但是LibreOffice的Less GNU通用公共許可證卻不兼容OpenOffice的Apache許可證。換句話説，LibreOffice可以隨意自由地從OpenOffice“借”代碼，但是OpenOffice卻根本無法從LibreOffice“借”到任何東西。嚴格地講，如果想從LibreOffice“借”來某個功能，OpenOffice必須完全從頭實現。",-1)),e[23]||(e[23]=i("p",null,"這一情況有可能會改變，尤其是當Apache OpenOffice比LibreOffice擁有更高的知名度的時候，然而LibreOffice的支持者們正在迅速擴張，它的社區非常活躍，短短3年間所做的要比OpenOffice.org十二年來做的還要多。",-1)),e[24]||(e[24]=i("p",null,"現在，除非你特別需要某個功能，使用OpenOffice還是LibreOffice幾乎沒有區別。但是，我斷定，除非發生某些不可預料的事情，否則LibreOffice的優勢將會越來越大。無論你選擇支持哪一方，幾年內，也許你會對它重新作出評價。",-1)),e[25]||(e[25]=i("hr",null,null,-1)),i("p",null,[e[8]||(e[8]=f("via: ",-1)),O(p,{href:"http://www.datamation.com/applications/apache-openoffice-vs.-libreoffice-1.html"},{default:r(()=>[...e[7]||(e[7]=[f("http://www.datamation.com/applications/apache-openoffice-vs.-libreoffice-1.html",-1)])]),_:1})]),i("p",null,[e[11]||(e[11]=f("譯者：",-1)),O(p,{href:"http://blog.csdn.net/tinyeyeser"},{default:r(()=>[...e[9]||(e[9]=[f("Mr小眼兒",-1)])]),_:1}),e[12]||(e[12]=f(" 校對：",-1)),O(p,{href:"https://github.com/wxy"},{default:r(()=>[...e[10]||(e[10]=[f("wxy",-1)])]),_:1})]),i("p",null,[e[15]||(e[15]=f("本文由 ",-1)),O(p,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[13]||(e[13]=[f("LCTT",-1)])]),_:1}),e[16]||(e[16]=f(" 原創翻譯，",-1)),O(p,{href:"http://linux.cn/"},{default:r(()=>[...e[14]||(e[14]=[f("Linux中國",-1)])]),_:1}),e[17]||(e[17]=f(" 榮譽推出",-1))])])}const w=t(c,[["render",L]]);export{A as __pageData,w as default};
